local C = NR.SpellCatalog
local byID = {}
for _, entry in ipairs(C.spells) do byID[entry.id] = entry end

function C.Get(spellID)
    if not NR.Number(spellID,1,10000000) or spellID%1~=0 then return nil end
    return byID[spellID] and NR.Copy(byID[spellID]) or nil
end

function C.ForSpec(specID)
    local out = {}
    if not NR.Number(specID,1,10000) or specID%1~=0 then return out end
    for _, entry in ipairs(C.spells) do
        for _, id in ipairs(entry.specs) do
            if id==specID then out[#out+1]=NR.Copy(entry); break end
        end
    end
    return out
end

function C.Info(spellID)
    if not NR.Number(spellID,1,10000000) or spellID%1~=0 then return "提醒",nil end
    local entry=byID[spellID]
    local info
    if C_Spell and C_Spell.GetSpellInfo then
        local ok,value=pcall(C_Spell.GetSpellInfo,spellID)
        if ok and NR.Public(value) and type(value)=="table" then info=value end
    end
    local name=info and info.name
    if not NR.Public(name) or type(name)~="string" or name=="" then name=entry and entry.name or "技能 "..spellID end
    local icon=info and info.iconID
    if not NR.Number(icon,1,100000000) then icon=entry and entry.icon or nil end
    return name,icon
end
